-- ================= SECCIÓN 1. CARACTERES GENERALES
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, orden)
VALUES (1, NULL, 'seccion', '1', 'c1', 'CARACTERES GENERALES', 1);
SET @seccion_id := LAST_INSERT_ID();

INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '1.1', 'Introducción – Proceso Constituyente', '<p>La Constitución Española de 1978 representa el paso de un Régimen autoritario a un Régimen Democrático Constitucional.</p><p>El proceso de la Constitución de 1978 se inició tras la muerte del General Franco, en 1975.</p><p>El instrumento preventivo previo que desbloqueó la situación del anterior régimen fue la ley 1/1977 de 4 de enero, la Ley para la Reforma Política.</p><p>Dicha ley, aprobada por las Cortes el 18 de noviembre de 1976, fue ratificada en Referéndum el día 15 de diciembre de ese mismo año, lo que permitió que finalmente se celebraran elecciones generales el día 15 de junio de 1977, las primeras en democracia.</p><p>Las fechas fundamentales del proceso son las siguientes:</p><p><strong>APROBACIÓN – 31 de octubre 1978 – Por las Cortes Generales</strong></p><p><strong>RATIFICACIÓN – 6 de diciembre de 1978 – Por el pueblo en Referéndum</strong></p><p><strong>SANCIÓN Y PROMULGACIÓN – 27 de diciembre de 1978 – Por el Rey</strong></p><p>PUBLICACIÓN – 29 de diciembre de 1978 – Se publica en el BOE. Entra en vigor.</p>', 1);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '1.2', 'Reformas', '<p>El texto constitucional ha tenido tres reformas:</p><p><strong>1ª reforma - 27 de agosto de 1992</strong></p><p>La primera reforma consistió en introducir las palabras “y pasivo” en el artículo 13.2 del texto constitucional para adaptarla al artículo 8B.1 del Tratado de la Unión Europea. Se trataba de que los ciudadanos de la UE residentes en España se pudiesen también presentar como candidatos en las elecciones municipales.</p><div class="uji-cita"><p><strong>(Art.13.2)</strong> Solamente los españoles serán titulares de los derechos reconocidos en el artículo 23, salvo lo que, atendiendo a criterios de reciprocidad, pueda establecerse por tratado o ley para el derecho de sufragio activo y pasivo en las elecciones municipales”.</p></div><p><strong>2º reforma - 27 de septiembre de 2011</strong></p><p>Se reforma el artículo 135 a fin de introducir el principio de estabilidad presupuestaria, límites al déficit estructural y a la emisión de deuda pública. Se trataba de ajustar la CE a los principios marcados por la UE.</p><p><strong>3º reforma - 15 de febrero de 2024</strong></p><p>Se reforma el artículo 49 con una nueva redacción más acorde con el momento actual, eliminando términos anticuados e introduciendo nuevos términos que reflejen un nuevo vocabulario más respetuoso.</p><p>(Art.49-1). Las personas con discapacidad ejercen los derechos previstos en este Título en condiciones de libertad e igualdad reales y efectivas</p>', 2);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '1.3', 'Características', '<p>La Constitución Española tiene las siguientes características:</p><p>Extensa: es una constitución larga, con muchos artículos, 169 y muchas disposiciones, 15. Algunos de los artículos son largos y complejos. Después de la Constitución de 1812, es la constitución más extensa.</p><p>Escrita: sigue la tradición del constitucionalismo continental europeo, donde las constituciones se redactan en un código escrito. Al contrario del constitucionalismo británico, que se basa en la costumbre.</p><p>Rígida: en lo relativo a los procedimientos para reformarla, ya que es difícil hacerlo por las exigencias de mayorías parlamentarias de 2/3 o 3/5 para reformarla.</p><p>Consensuada: por la particIpación de las distintas fuerzas políticas del momento, lo que, por otro lado, da lugar a diferentes interpretaciones sobre la semántica de algunos artículos.</p><p>Popular: el origen está en el pueblo español. Fue elaborada por los representantes del pueblo, y ratificada en referéndum.</p>', 3);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '1.4', 'Estructura y contenidos', '<p>Está estructurada en Títulos, Capítulos, Secciones y Artículos.</p><p>En total tiene: un Preámbulo, 11 Títulos (1 Preliminar, 10 numerados), 15 Disposiciones (4 adicionales, 9 transitorias, 1 derogatoria, 1 final).</p><ul class="uji-lista"><li>Preámbulo - Sin artículos.</li><li>Título preliminar - (Del art. 1 al 9). Los principios generales del ordenamiento constitucional.</li><li>Título I - ( Del art. 10 al 55 ). De los derechos y deberes fundamentales.</li><li>Capítulo 1º: (Del art. 11 al 13) De los españoles y los extranjeros.</li><li>Capítulo 2º: (Del art. 14 al 38) Derechos y libertades.</li><li>Sección 1ª – (Del art. 15 al 29) De los derechos fundamentales y las libertades públicas.</li><li>Sección 2º - (Del art. 30 al 38) De los derechos y deberes de los ciudadanos.</li><li>Capítulo 3º: (Del art. 39 al 52) De los principios rectores de la política social y económica.</li><li>Capítulo 4º: (Del art. 53 al 54) De las garantías de las libertades y derechos fundamentales.</li><li>Capítulo 5º: (art. 55)</li><li>Título II – (Del art. 56 al 65) – De la Corona</li><li>Título III – (Del art. 66 al 96) – De las Cortes Generales</li><li>Capítulo 1º – (Del art. 66 al 80) – De las Cámaras</li><li>Capítulo 2º – (Del art. 81 al 92) – De la elaboración de las Leyes</li><li>Capítulo 3º – (Del art. 93 al 96) – De los Tratados Internacionales</li><li>Título IV – (Del art. 97 al 107) – Del Gobierno y la Administración</li><li>Título V – (Del art. 108 al 116) – De las relaciones entre el Gobierno y Las Cortes</li><li>Título VI– (Del art. 117 al 127) – Del Poder Judicial</li><li>Título VII – (Del art. 128 al 136) – Economía y Hacienda</li><li>Título VIII – (Del art. 137 al 158) – De la organización territorial del Estado</li><li>Capítulo 1º – (Del art. 137 al 139) – Principios Generales</li><li>Capítulo 2º – (Del art. 140 al 142) – De la Administración Local</li><li>Capítulo 3º – (Del art. 143 al 158) – De las Comunidades Autónomas</li><li>Título IX – (Del art. 159 al 165) – Del Tribunal Constitucional</li><li>Título X – (Del art. 166 al 169) – De la Reforma Constitucional</li><li>4 Disposiciones Adicionales</li><li>9 Disposiciones Transitorias</li><li>1 Disposición Derogatoria</li><li>1 Disposición Final</li></ul>', 4);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '1.5', 'Partes', '<p>También se divide la Constitución en dos partes, dependiendo de su contenido:</p><p><strong>Parte Dogmática</strong></p><p>La parte que alude a unos principios generales y a unos derechos, libertades y deberes. Son el Preámbulo, el Título Preliminar y el Título Primero.</p><p><strong>Parte Orgánica</strong></p><p>Son las normas de organización del Estado y sus instituciones principales (Cortes Generales, Gobierno, Corona, Poder Judicial, CCAA, Tribunal Constitucional).</p><p>Explica cómo se componen los poderes públicos, cómo se organizan y cómo se relacionan.</p>', 5);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '1.6', 'Historia de las constituciones', '<p><strong>A) 1812 - La Constitución de Cádiz</strong></p><p>La Constitución de Cádiz, aprobada el 19 de marzo de 1812, festividad de San José, conocida por eso como la Pepa, es la primera Constitución propiamente española, ya que el Estatuto de Bayona de 1808 no dejó de ser una “Carta otorgada” marcada por el sello napoleónico.La constitución de 1812 enlazaba con las Leyes tradicionales de la Monarquía española pero, al mismo tiempo, incorporaba principios del liberalismo democrático, tales como la soberanía nacional y la separación de poderes.La Constitución de 1812 tuvo una vigencia efímera. Fernando VII la derogó a su vuelta a España en 1814, implantando el más férreo absolutismo durante seis años.</p><p><strong>B) 1834 - El Estatuto Real</strong></p><p>El Estatuto Real de 1834 fue una constitución flexible, breve e incompleta. De tan sólo 50 artículos, que regulaban la organización de las Cortes, sus funciones y sus relaciones con el Rey, no recogía ningún título dedicado a la Monarquía ni a sus Ministros y, sobre todo, no contenía una declaración de derechos fundamentales del ciudadano. Se trató de una Carta Otorgada.</p><p><strong>C) La Constitución de 1837</strong></p><p>La Constitución de 1837 fue fruto de la crisis del Estatuto Real, y sobrevivió dificultosamente hasta su derogación definitiva por la Constitución de 1845.</p><p>La Constitución de 1837 incorporó, por vez primera en nuestra historia constitucional, una declaración sistemática y homogénea de derechos.</p><p><strong>D) La Constitución de 1845</strong></p><p>La Constitución de 1845 fue el resultado del esfuerzo de los moderados por conciliar tradición y revolución.En el texto de 1845 ya no aparece, como en las Constituciones de 1812 y 1837, la fórmula revolucionaria de la soberanía de la nación, sino que se revierte a la fórmula tradicional histórica de la soberanía compartida por las Cortes y el Rey.</p><p><strong>E) La Constitución de 1869</strong></p><p>La Constitución de 1869 contiene los puntos básicos que se consideraban alma misma de la Revolución del 1868, los cuales quedaron consignados en el texto constitucional: soberanía nacional, sufragio universal, concepción de la Monarquía como poder constituido y declaración de derechos.</p><p>Pero, sin duda, lo más original de la Constitución era su amplia declaración de derechos en el Título I (casi la tercera parte de los artículos), especie de Carta Magna del liberalismo español hasta la Segunda República, que siempre proyectará su sombra a lo largo del resto de la historia española como garantía, en cuestiones fundamentales. Como el juicio por jurado, la acción popular, el derecho de asociación, la libertad de enseñanza o la libertad de cultos (una de las más apasionadamente debatidas en aquellas Cortes y auténtica novedad en nuestro constitucionalismo).</p><p><strong>F) La Constitución de 1876</strong></p><p>La Constitución de 1876 es un texto breve y abierto de 89 artículos, que permite mantener la alternancia de partidos. El texto vuelve a adoptar la soberanía del Rey con las Cortes.</p><p>En 1923, el golpe de Estado de Primo de Rivera involucra al ejército y suspende la Constitución y, en 1931, tras el fracaso de la Dictadura, sucumbe la Monarquía.</p><p><strong>G) La Constitución de 1931</strong></p><p>El 9 de diciembre de 1931, el Presidente de las Cortes, Julián Besteiro, promulgó la Constitución de la Segunda República española. Nuestra historia constitucional recoge en este texto, por primera vez, un Estado distinto del unitario que había existido desde la Constitución de Cádiz hasta la Restauración canovista.Los principios políticos que inspiran la Constitución de 1931 son: la democracia, el regionalismo, el laicismo y la economía social.</p>', 6);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '1.7', 'Influencia de otras constituciones', '<p>La Constitución de 1978, a juicio de quienes la elaboraron y estudiaron, tiene dos fuentes primordiales de inspiración: la Ley Fundamental de Bonn de 1949 y la Constitución de la República española de 1931.</p><p>No fueros éstas las únicas influencias. Desde el preámbulo hasta la última disposición, la carta magna que nació de la Transición también recoge aportaciones italianas, portuguesas y francesas.</p><p>"El primer texto a consultar era lógicamente la Constitución Republicana del 31. Pero también se tuvo muy en cuenta la Ley Fundamental de Bonn, la Constitución italiana, algún punto muy concreto de la Constitución de Portugal, y, en algún supuesto, la Constitución de la V República francesa".</p><p>"La alemana se tuvo muy en cuenta, con la italiana, al tiempo de elaborar el Titulo VIII. En los demás casos la influencia de los otros textos fue menos decisiva".</p><p>"De entre las Constituciones europeas fue trascendental la Ley Fundamental de Bonn de 1949, que influyó incluso en el Artículo 1: \'España se constituye en un Estado social y Democrático de Derecho...".</p><p>También de la alemana procede "la moción de censura constructiva, que exige un candidato alternativo y que, en caso de triunfar la moción, es investido Presidente (Artículos 113 y 114)".</p><p>Guerra añade: "Se tuvo en cuenta la Constitución italiana para la estructura del Poder Judicial, para algunos aspectos de la estructura regional y para la responsabilidad de los poderes públicos en la tarea de conquistar la plena libertad e igualdad de los ciudadanos (Artículo 9)".</p><p>El socialista recuerda la influencia de las Constituciones históricas españolas: "La Constitución de Cádiz de 1812 para temas generales de Libertad y concepción del Nuevo Régimen; y la de 1931, de la II República".</p>', 7);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '1.8', 'Título Preliminar', '<p><strong>Los principios fundamentales y los valores superiores</strong></p><p>Se recogen en el Título Preliminar, con 9 artículos, del 1 al 9.</p><p>- Estado Social y Democrático de Derecho.</p><div class="uji-cita"><p><strong>(art. 1.1)</strong> España se constituye en un Estado social y democrático de Derecho, que propugna como valores superiores de su ordenamiento jurídico la libertad, la justicia, la igualdad y el pluralismo político”.</p></div><p>- Se declara España como un Estado, un Estado social.</p><div class="uji-cita"><p><strong>(art. 9.2) - Estado Social,</strong> que intentará promover las condiciones, remover obstáculos y facilitar la participación de todos los ciudadanos para que las condiciones de igualdad sean efectivas y reales”.</p></div><p>Cómo tal Estado Social formula unas libertades y derechos en el capítulo 2º del Título I. Asimismo enumera unos Principios rectores de la política, muchos de los cuales cimientan ese Estado Social, en el Capítulo Tercero del Título I.</p><p><strong>- Soberanía Nacional</strong></p><div class="uji-cita"><p><strong>(art. 1.2)</strong> La Soberanía nacional reside en el pueblo español, del que emanan los poderes del Estado”.</p></div><p><strong>- Monarquía Parlamentaria</strong></p><div class="uji-cita"><p><strong>(art. 1.3)</strong> La forma política del Estado es la Monarquía Parlamentaria”.</p></div><p>Las dos instituciones que dan sentido a esta Monarquía parlamentaria, la Corona y las Cortes, son precisamente los dos siguientes Títulos de la CE: Título II – De la Corona, y Título III – De las Cortes</p><p><strong>- Unidad de la Nación española</strong></p><div class="uji-cita"><p><strong>(art. 2)</strong> La Constitución se fundamenta en la indisoluble unidad de la nación española, patria común de todos los españoles, y reconoce y garantiza el derecho a la autonomía de las nacionalidades y regiones que la integran y la solidaridad entre ellas”.</p></div><p>En este artículo encontramos hasta tres principios que rigen la organización territorial del Estado:</p><ul class="uji-lista"><li>Unidad de la Nación española.</li><li>- Autonomía de las nacionalidades y regiones.</li><li>- Solidaridad entre ellas.</li></ul><p><strong>- Idioma: Castellano</strong></p><div class="uji-cita"><p><strong>(art. 3.1)</strong> El castellano es la lengua española oficial del Estado. Todos los españoles tienen el deber de conocerla y el derecho a usarla”.</p></div><div class="uji-cita"><p><strong>(art. 3.2)</strong> Las demás lenguas españolas, serán también oficiales en las respectivas Comunidades Autónomas, de acuerdo con sus Estatutos”.</p></div><div class="uji-cita"><p><strong>(art. 3.3)</strong> La riqueza dela distintas modalidades lingüísticas de España es un patrimonio cultural que será objeto de especial respeto y protección”.</p></div><p><strong>- Bandera</strong></p><div class="uji-cita"><p><strong>(art. 4.1)</strong> La bandera de España está formada por tres franjas horizontales, roja, amarilla y roja, siendo la amarilla de doble anchura que cada una de las rojas”.</p></div><div class="uji-cita"><p><strong>(art. 4.2)</strong> Los Estatutos podrán reconocer banderas y enseñas propias delas Comunidades Autónomas. Estas se utilizarán junto a la bandera de España en sus edificios públicos y en sus actos oficiales”.</p></div><p><strong>- Capital de España</strong></p><div class="uji-cita"><p><strong>(art. 5)</strong> La capital de España es la villa de Madrid”.</p></div><p><strong>- Partidos Políticos</strong></p><div class="uji-cita"><p><strong>(art. 6)</strong> Los partidos políticos expresan el pluralismo político, concurren a la formación y manifestación de la voluntad popular y son instrumento fundamental para la participación política. Su creación y el ejercicio de su actividad son libres dentro del respeto a la Constitución y a la ley. Su estructura interna y funcionamiento deberán ser democráticos”.</p></div><p><strong>- Los Sindicatos y Asociaciones Empresariales</strong></p><div class="uji-cita"><p><strong>(art. 7)</strong> Los sindicatos de trabajadores y las asociaciones empresariales contribuyen a la defensa y la promoción de los intereses económicos y sociales que les son propios. Su creación y el ejercicio de su actividad son libres dentro del respeto a la CE y a la ley. Su estructura interna y funcionamiento deberán ser democráticos”.</p></div><p><strong>- Las Fuerzas Armadas</strong></p><div class="uji-cita"><p><strong>(art. 8.1)</strong> Las Fuerzas Armadas, constituidas por el Ejército de Tierra, la Armada y el Ejército del Aire, tienen como misión garantizar la soberanía e independencia de España, defender su integridad territorial y el ordenamiento constitucional”.</p></div><div class="uji-cita"><p><strong>(art. 8.2)</strong> Una ley orgánica regulará las bases de la organización militar conforme a los principios de la presente Constitución”.</p></div><p><strong>- Garantías Jurídicas</strong></p><p>El artículo 9, para terminar el Título Preliminar, comienza con la obligación de ciudadanos y poderes públicos de respetar la Constitución y las leyes.</p><div class="uji-cita"><p><strong>(art.9.1)</strong> Los ciudadanos y los poderes públicos están sujetos a la Constitución y al resto del ordenamiento jurídico”.</p></div><p>Invoca entonces a los poderes públicos para que con su acción contribuyan a que la Constitución y sus valores estén presentes en la vida pública.</p><div class="uji-cita"><p><strong>(art. 9.2)</strong> Corresponde a los poderes públicos promover las condiciones para que la libertad y la igualdad del individuo y de los grupos en que se integra sean reales y efectivas; remover los obstáculos que impidan o dificulten su plenitud y facilitar la participación de todos los ciudadanos en la vida política, económica, cultural y social”.</p></div><p>Y también refiere a las garantías jurídicas que garantiza la Constitución.</p><div class="uji-cita"><p><strong>(art.9.3)</strong> La Constitución garantiza el principio de legalidad, la jerarquía normativa, la publicidad de las normas, la irretroactividad de las disposiciones sancionadoras no favorables o restrictivas de derechos individuales, la seguridad jurídica, la responsabilidad y la interdicción de la arbitrariedad de los poderes públicos”.</p></div>', 8);

-- ================= SECCIÓN 2. DERECHOS FUNDAMENTALES Y SU PROTECCIÓN
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, contenido_html, orden)
VALUES (1, NULL, 'seccion', '2', 'c2', 'DERECHOS FUNDAMENTALES Y SU PROTECCIÓN', '<p>Estos derechos se encuentran contemplados y regulados en el Título I de la CE.</p><p>El artículo 10 como apertura del Título establece que:</p><div class="uji-cita"><p><strong>(art. 10)</strong> La dignidad de la persona, los derechos que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley a los derechos de los demás son fundamento del orden político y de la paz social.</p></div><p>Las normas relativas a los derechos fundamentales y a las libertades que la Constitución reconoce se interpretarán de conformidad con la Declaración Universal de Derechos Humanos y los tratados y acuerdos internacionales sobre las mismas materias ratificados por España”.</p><p>Esos Tratados y Acuerdos Internacionales a los que hace alusión el artículo son:</p><p><strong>La Declaración Universal de los Derechos Humanos de la ONU de 1948</strong></p><p><strong>El Pacto Internacional de Derechos Civiles y Políticos de 1966</strong></p><p>El Pacto Internacional de Derechos Económicos, Sociales y Culturales de 1966</p><p>y la Convención Europea de Derechos del Hombre, del Consejo de Europa de 1950.</p>', 2);
SET @seccion_id := LAST_INSERT_ID();

INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '2.1', 'DERECHOS Y LIBERTADES (Capítulo 2 del Título I)', '<p>El artículo 14 de la CE consagra la igualdad de todos, y que nadie puede ser discriminado por razón de:</p><ul class="uji-lista"><li>Nacimiento</li><li>Raza</li><li>Sexo</li><li>Religión</li><li>Opinión</li><li>Cualquier otra condición o circunstancia personal o social</li></ul>', 1);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '2.2', 'Sección 1º: De los Derechos fundamentales y las libertades públicas', '<p><strong><span class="uji-ref" data-norma="CE" data-arts="15">art. 15</span> – Derecho a la vida y a la integridad física y moral</strong></p><p>La Constitución reconoce el derecho a la vida como el más importante de todos. Por ello declara la abolición de la Pena de Muerte, con la excepción de lo que puedan establecer las leyes penales militares para tiempos de guerra, aunque posteriormente, por LO 11/1995, de 27 de noviembre, se abolió también la pena de muerte en tiempos de guerra.</p><p>Asimismo, se declara que “nadie podrá ser sometido a torturas ni a penas o tratos inhumanos o degradantes”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="16">art. 16</span> – Libertad ideológica, religiosa y de culto</strong></p><p>Consagra las libertades de pensar libremente, profesar una fé y ejercerla.</p><p>“Se garantizan las libertades ideológica, religiosa y de culto para los individuos y comunidades, sin más limitación en sus manifestaciones que la necesaria para el mantenimiento del orden público protegido por la ley”.</p><p>Nadie podrá ser obligado a declarar sobre su ideología, religión o creencias.</p><p>Ninguna confesión tendrá carácter estatal. Los poderes públicos tendrán en cuenta las creencias religiosas de la sociedad española y mantendrán las consiguientes relaciones de cooperación entre la Iglesia Católica y las demás confesiones”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="17">art. 17</span> – Libertad personal</strong></p><p>“Todos tienen derecho a la libertad y seguridad. Nadie podrá ser privado de su libertad, sino con la observación de lo establecido en este artículo y en los casos y las formas previstos en la ley”.</p><p>Detención preventiva.</p><p>“No podrá durar más del tiempo estrictamente necesario para las averiguaciones tendentes al esclarecimiento de los hechos. En todo caso, en el plazo máximo de 72 horas, el detenido deberá ser puesto en libertad o a disposición de la autoridad judicial”.</p><p>Derechos del detenido.</p><p>“Debe ser informado de forma inmediata, de modo que le sea comprensible, de sus derechos y de las razones de su detención. No podrá ser obligado a declarar. Se garantiza la Asistencia de abogado en las diligencias policiales y judiciales, en los términos que la ley establezca”.</p><p>Prisión provisional:</p><p>“Tendrá la duración máxima que determine la Ley”.</p><p>“La ley regulará un procedimiento de Habeas Corpus, para proteger a toda persona detenida ilegalmente. Mediante el mismo se obtiene la inmediata puesta a disposición de la autoridad judicial competente de dicha persona”.</p><p>(art. 18) – Derechos al Honor, Intimidad personal y familiar, a la inviolabilidad del domicilio, al secreto de las comunicaciones y límites al uso de la informática.</p><div class="uji-cita"><p><strong>(18.1)</strong> La CE garantiza el derecho al Honor, a la intimidad familiar y personal y a la propia imagen”.</p></div><div class="uji-cita"><p><strong>(18.2)</strong> El domicilio es inviolable. Ninguna entrada o registro podrán hacerse sin el consentimiento del titular o resolución judicial, salvo en caso de flagrante delito”.</p></div><div class="uji-cita"><p><strong>(18.3)</strong> Se garantiza el secreto de las comunicaciones, y en especial, las postales, telegráficas y telefónicas, salvo resolución judicial”.</p></div><div class="uji-cita"><p><strong>(18.4)</strong> La ley limitará el uso de la informática para garantizar el honor y la intimidad personal y familiar de los ciudadanos y el pleno ejercicio de sus derechos”.</p></div><p><strong><span class="uji-ref" data-norma="CE" data-arts="19">art. 19</span> – Libertad de residencia y circulación</strong></p><p>Es un derecho que tienen todos los españoles de elegir libremente su residencia y circular por el territorio nacional. Igualmente tienen el derecho a entrar y salir libremente de España en los términos que establezca la ley. En ningún caso este derecho podrá ser limitado por motivos políticos o ideológicos.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="20">art. 20</span> – Libertad de expresión</strong></p><p>Un derecho básico de cualquier estado democrático. La CE reconoce más que una única libertad de expresión, una amplia forma de libertades que tienen por eje común la libertad de emisión y transmisión de las opiniones.</p><p>Concretamente, el artículo 20 protege los siguientes derechos:</p><p>A expresar y difundir libremente pensamientos, ideas y opiniones.</p><p><strong>A la producción literaria, artística, científica y técnica</strong></p><p><strong>A la libertad de cátedra</strong></p><p><strong>A comunicar y recibir libremente información veraz</strong></p><p>La CE establece asimismo unos mecanismos que garanticen y protejan la libertad de expresión: Regula la cláusula de conciencia y el secreto profesional. Y prohíbe la Censura Previa y el secuestro de publicaciones, grabaciones y otros medios de comunicación, salvo lo que establezca una resolución judicial.</p><p>Estas libertades del artículo 20 sólo tienen un límite en el respeto a los derechos del Título I, especialmente en el Derecho al Honor, Intimidad, a la propia imagen y a la protección de la juventud y la infancia.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="21">art. 21</span> – Derecho de reunión</strong></p><p>Es una libertad clásica. La CE la reconoce cuando es pacífica y sin armas, no necesitando autorización previa para su ejercicio. No obstante, “cuando la manifestación transcurra por lugares de tránsito público se dará comunicación a la autoridad, que sólo podrá prohibirla cuando existan razones fundadas de alteración del orden público, con peligro para personas y bienes.</p><p>Dicha prohibición podrá recurrirse ante los Tribunales ordinarios, que decidirán en un procedimiento sumario y urgente”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="22">art. 22</span> – Derecho de Asociación</strong></p><p>Es un derecho el de crear asociaciones y pertenecer a ellas. Simplemente exige la inscripción de la Asociación en un Registro a efectos de publicidad.</p><p>La CE prohíbe las asociaciones secretas y las de carácter paramilitar.</p><p>También se declaran ilegales las asociaciones que persiguen fines o utilicen medios tipificados como delitos.</p><p>La CE establece como garantía de este derecho el que sólo podrán ser disueltas o suspendidas en virtud de una resolución judicial motivada.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="23">art. 23</span> – Derecho de participación</strong></p><p>A participar en los asuntos públicos, bien directamente o por medio de representantes, que serán elegidos libremente en elecciones por sufragio universal.</p><p>También derecho a acceder en condiciones de igualdad a las funciones y cargos públicos, con los requisitos que marquen las leyes.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="24">art. 24</span> – Administración de Justicia, derechos</strong></p><p>Establece una serie de garantías y principios jurídicos, que van a proteger a los ciudadanos en su relación con la Administración. de Justicia.</p><p>Tutela efectiva de Jueces y Tribunales. Acceso universal.</p><p>Derecho al juez ordinario, determinado por ley.</p><p>Defensa y asistencia de Letrado.</p><p>Ser informado de la acusación formulada.</p><p>Proceso público, sin dilaciones y con garantías.</p><p>Utilizar los medios de prueba pertinentes para su defensa.</p><p>No declara contra sí mismo.</p><p>No confesarse culpable.</p><p>Presunción de inocencia.</p><p>La ley regulará los casos en que, por razón de parentesco o secreto profesional, no se estará obligado a declarar sobre hechos presuntamente delictivos.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="25">art. 25</span> – Principio de legalidad penal y administrativa</strong></p><p>“Nadie podrá ser condenado o sancionado por acciones u omisiones que en el momento de producirse no constituyan delito, falta o infracción administrativa, según la legislación vigente en aquel momento”.</p><p>Reinserción - Trabajo remunerado, beneficios de la SS, acceso a la cultura y al desarrollo integral de su personalidad.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="26">art. 26</span> – Tribunales de Honor</strong></p><p>“Quedan prohibidos los tribunales de honor en el ámbito de la Administración civil y de las organizaciones profesionales”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="27">art. 27</span> – Derecho a la educación</strong></p><p>“Tendrá como objeto el pleno desarrollo de la personalidad humana”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="28.1">art. 28.1</span> – Libertad sindical</strong></p><p>“Todos tienen derecho a sindicarse libremente”, para la defensa de los intereses profesionales de los trabajadores.</p><p>Derecho a fundar sindicatos.</p><p>Derecho a afiliarse al sindicato de su elección.</p><p>Derecho de los sindicatos a formar confederaciones y pertenecerá a organizaciones internacionales.</p><p>Derecho a no ser obligado a afiliarse.</p><p>Una Ley Orgánica regulará las peculiaridades de su ejercicio para los funcionarios públicos.</p><p>Fuerzas Armadas y cuerpos de disciplina militar tienen exceptuada la libertad sindical.</p><p>El Cuerpo de Policía Nacional tiene limitado este derecho.</p><p>Jueces, Magistrados y Fiscales mientras se hallen en activo no pueden pertenecer a partidos políticos o sindicatos. Podrán pertenecer a asociaciones profesionales.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="28.2">art. 28.2</span> – Derecho a la Huelga</strong></p><p>“Derecho de los trabajadores a la huelga para la defensa de sus intereses. Habrá unas garantías para asegurar el mantenimiento de los servicios esenciales de la comunidad”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="29">art. 29</span> – Derecho de petición</strong></p><p>Es un derecho de carácter político, y supone la posibilidad de todo ciudadano de dirigirse a las autoridades refiriéndose a cuestiones que le incumben y de cuya resolución son competentes aquellas. Se trata de cualquier sugerencia, iniciativa, información, queja o suplica que tenga como destinatario a cualesquiera Poderes Públicos.</p><p>“Todos los españoles tienen el derecho de petición individual y colectiva, por escrito, en la forma y con los efectos que determine la ley”.</p><p>“Los miembros de las FFAA o institutos armados o de los cuerpos sometidos a disciplina militar podrán ejercer este derecho sólo individualmente y con arreglo a lo dispuesto en la legislación específica”.</p>', 2);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '2.3', 'Sección 2º: Derechos y deberes de los ciudadanos', '<p>Están regulados en la sección 2º del Capítulo II del Título I de la CE.</p><p>Los artículos 30 y 31 se refieren a deberes constitucionales.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="32">art. 32</span> – Derecho al matrimonio</strong></p><p>“El derecho del hombre y la mujer a contraer matrimonio con plena igualdad jurídica. La Ley regulará las formas de matrimonio, la edad y capacidad para contraerlo, los derechos y deberes de los cónyuges, las causas de separación y disolución, y sus efectos”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="33">art. 33</span> – Derecho a la propiedad privada y a la herencia</strong></p><p>La función social de estos derechos determina el contenido de los mismos.</p><p>“Nadie puede ser privado de sus bienes y derechos sino por causa justificada de utilidad pública o interés social, mediante la correspondiente indemnización y de conformidad con lo dispuesto por las leyes”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="34">art. 34</span> – Derecho de fundación</strong></p><p>“Derecho de fundación para fines de interés general. Son ilegales las que persiguen fines o utilicen medios tipificados como delitos. Sólo podrán ser disueltas o sus suspendidas sus actividades en virtud de resolución judicial motivada”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="35">art. 35</span> – Derecho al trabajo</strong></p><p>La Constitución reconoce el derecho al trabajo de todos los españoles. Los derechos que se regulan son inherentes a la relación laboral:</p><p>Libre elección de profesión u oficio.</p><p>Promoción profesional.</p><p>Remuneración suficiente.</p><p>No discriminación por razón de sexo.</p><div class="uji-cita"><p><strong>(art. 35.2)</strong> Una ley regulará el derecho al trabajo mediante el Estatuto de los Trabajadores”. RD 1/1995, de 24 de marzo.</p></div><p><strong><span class="uji-ref" data-norma="CE" data-arts="36">art. 36</span> – Los Colegios Profesionales</strong></p><p>“son entes que se encargan del control del ejercicio de las profesiones tituladas. Su régimen jurídico será regulado por una ley. Su estructura interna y funcionamiento deberán ser democráticos”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="37.1">art. 37.1</span> – Negociación colectiva laboral</strong></p><p>“La ley garantizará el derecho a la negociación colectiva laboral entre los representantes de los trabajadores y empresarios, así como la fuerza vinculante de los convenios”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="37.2">art. 37.2</span> – Medidas de conflicto colectivo</strong></p><p>“Se reconoce el derecho de trabajadores y empresarios a adoptar medidas de conflicto colectivo. La ley que regule el ejercicio de este derecho, sin perjuicio de las limitaciones que puedan establecer, incluirá las garantías precisas para asegurar el funcionamiento de los servicios esenciales de la comunidad”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="38">art. 38</span> – Libertad de empresa</strong></p><p>Reconoce la libertad de empresa en el marco de la economía de mercado.</p><p>“Los poderes públicos garantizan y protegen su ejercicio y la defensa de la productividad, de acuerdo con las exigencias de la economía general, y en su caso, de la planificación”.</p>', 3);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '2.4', '“Principios rectores de la política social y económica”', '<p>Es el Capítulo Tercero del Título I de la Constitución.</p><p>Más que auténticos derechos, lo que aparece recogido en los artículos del 39 al 52 de la CE son mandatos morales que deben informar la legislación positiva, la práctica judicial y la actuación de los poderes públicos. O sea, que no se consideran fundamentales, pero si derechos a alcanzar para un mejor desarrollo de un estado democrático.</p><p>Se podrían categorizar según los grupos de protección a los que hace alusión:</p><p>1 – Protección a colectivos:</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="39.1">art. 39.1</span> – Familia</strong></p><p>“Los poderes públicos aseguran la protección social, económica y jurídica de la familia”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="39.2">art. 39.2</span> – Infancia</strong></p><p>“Protección integral de los hijos, iguales ante la ley con independencia de su filiación”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="48">art. 48</span> – Juventud</strong></p><p>“Participación libre y eficaz de la juventud en el desarrollo político, social, económico y cultural”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="49">art. 49</span> – Discapacidad</strong></p><p>“Los poderes públicos impulsarán las políticas que garanticen la plena autonomía personal y la inclusión social de las personas con discapacidad, en entornos universalmente accesibles. ”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="50">art. 50</span> – Tercera Edad</strong></p><p>“Promover pensiones adecuadas y su bienestar”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="42">art. 42</span> – Emigrantes</strong></p><p>“Proteger sus derechos económicos y sociales, y orientar su retorno”.</p><p><strong>2- Principios laborales y de Seguridad Social (art. 40 y 41)</strong></p><p>Redistribución de la Renta.</p><p>Seguridad e higiene en el trabajo.</p><p>Pleno empleo.</p><p>Descanso necesario.</p><p>Sistema público de la Seguridad Social.</p><p>Formación profesional.</p><p><strong>3- Servicios Sociales</strong></p><p><strong><span class="uji-ref" data-norma="CE" data-arts="43.1">art. 43.1 y 43.2</span> – Derecho a la Salud</strong></p><p>“Protección de la salud, medidas preventivas, prestaciones y servicios necesarios”.</p><div class="uji-cita"><p><strong>(art. 43.3)</strong> Fomentar la educación sanitaria, la educación física y el deporte”.</p></div><p><strong><span class="uji-ref" data-norma="CE" data-arts="44">art. 44</span> – Derecho a la Cultura</strong></p><p>“Promover y tutelar el acceso a la cultura como derecho universal”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="45">art. 45</span> – Derecho al Medio Ambiente</strong></p><p>“Derecho de todos, y deber de su conservación. Protección de los recursos naturales”.</p><p>(art.46) – Derecho al Patrimonio.</p><p>”Conservación y enriquecimiento del patrimonio histórico, cultural y artístico de los pueblos de España”.</p><p>(art.47) – Derecho a la vivienda.</p><p>“Derecho a disfrutar de una vivienda digna y adecuada de todos los españoles”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="51">art. 51</span> – Derechos como consumidores</strong></p><p>“Se protege mediante procedimientos eficaces la seguridad, la salud y los legítimos intereses de consumidores y usuarios”.</p><p>(art.52) – Derecho a asociarse profesionalmente en Organizaciones Profesionales.</p>', 4);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '2.5', 'Garantías de los derechos fundamentales y de las libertades públicas (Capítulo IV del Título I)', '<p>Las libertades y derechos de los tres primeros Capítulos del Título I (art. 10 al 52) se sostienen en un sistema de defensas y garantías de manera que cualquier ciudadano puede exigir para que esas libertades y derechos se hagan efectivos.</p><p>(art.53) - Establece distinción entre los derechos y libertades y formula para cada tipo una forma de garantizarlos y defenderlos.</p><p>Nivel superior de protección:</p><p>Para los derechos y libertades fundamentales (art. 16 a 29), junto con el principio de igualdad (art.14).</p><p>a) Vinculan a todos los poderes públicos.</p><p>b) Para el desarrollo de estos derechos se requiere ley orgánica (art. 14 a 29).</p><p>Esa ley orgánica es susceptible de recurso de inconstitucionalidad si no respeta el contenido esencial del derecho.</p><p>Se puede pedir la tutela de los tribunales ordinarios por un procedimiento preferente y sumario. También a la libertad de conciencia (art.30.2).</p><p>Es posible interponer recurso de amparo ante el Tribunal Constitucional ante la violación de uno de estos derechos. También de la libertad de conciencia.</p><p>Nivel Medio de protección:</p><p>Para el resto de derechos y libertades, reconocidos en el Capítulo Segundo.</p><p>a) Vinculan a todos los poderes públicos.</p><p>b) Se desarrollan por ley ordinaria.</p><p>Esa ley orgánica es susceptible de recurso de inconstitucionalidad si no respeta el contenido esencial del derecho.</p><p>Nivel mínimo de protección:</p><p>Esta protección afecta a los principios rectores de la política económica y social (Capítulo Tercero, art 39 a 52).</p><p>Son mandatos morales que deben informar la legislación positiva, la práctica judicial y la actuación de los poderes públicos.</p><p>Sólo podrán ser alegados ante la Jurisdicción ordinaria de acuerdo con lo que dispongan las leyes que lo desarrollen.</p>', 5);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '2.6', 'Suspensión de los derechos fundamentales y de las libertades públicas', '<p>La propia Constitución prevé aquellos aquellos casos en los que algunos derechos y libertades pueden ser restringidos o suspendidos.</p><div class="uji-cita"><p><strong>(art 55.1) -CE</strong> Los derechos reconocidos en los artículos 17, 18, apartados 2 y 3, artículos 19, 20, apartados 1, a) y d), y 5, artículos 21, 28, apartado 2, y artículo 37, apartado 2, podrán ser suspendidos cuando se acuerde la declaración del estado de excepción o de sitio en los términos previstos en la Constitución. Se exceptúa de lo establecido anteriormente el apartado 3 del artículo 17 para el supuesto de declaración de estado de excepción”.</p></div><div class="uji-cita"><p><strong>(art 55.2) - CE</strong> Una ley orgánica podrá determinar la forma y los casos en los que, de forma individual y con la necesaria intervención judicial y el adecuado control parlamentario, los derechos reconocidos en los artículos 17, apartado 2, y 18, apartados 2 y 3, pueden ser suspendidos para personas determinadas, en relación con las investigaciones correspondientes a la actuación de bandas armadas o elementos terroristas.La utilización injustificada o abusiva de las facultades reconocidas en dicha ley orgánica producirá responsabilidad penal, como violación de los derechos y libertades reconocidos por las leyes”.</p></div><p>La Ley Orgánica que desarrolla los estados de alarma, excepción y sitio es la LO 4/1981. A esta LO se hace referencia también en el artículo 116 de la Constitución:</p><p>116.1. CE - Una ley orgánica regulará los estados de alarma, de excepción y de sitio, y las competencias y limitaciones correspondientes..</p><p>En la LO citada encontramos los criterios o motivos por los que se podrá aplicar cada uno de los diferentes estados, además de su ámbito, y otra información ya reseñada aquí: duración, declaración, etc.</p><p>El estado de alarma se podrá declarar por:</p><p>a) Catástrofes, calamidades o desgracias públicas, tales como terremotos, inundaciones, incendios urbanos y forestales o accidentes de gran magnitud.</p><p>b) Crisis sanitarias, tales como epidemias y situaciones de contaminación graves.</p><p>c) Paralización de servicios públicos esenciales para la comunidad, cuando no se garantice lo dispuesto en los artículos veintiocho, dos, y treinta y siete, dos, de la Constitución, concurra alguna de las demás circunstancia o situaciones contenidas en este artículo.</p><p>d) Situaciones de desabastecimiento de productos de primera necesidad.</p><p>116.2 - CE - El estado de alarma será declarado por el Gobierno mediante decreto acordado en Consejo de Ministros por un plazo máximo de quince días, dando cuenta al Congreso de los Diputados, reunido inmediatamente al efecto y sin cuya autorización no podrá ser prorrogado dicho plazo. El decreto determinará el ámbito territorial a que se extienden los efectos de la declaración.</p><p>El estado de excepción se podrá declarar:</p><p>Cuando el libre ejercicio de los derechos y libertades de los ciudadanos, el normal funcionamiento de las instituciones democráticas, el de los servicios públicos esenciales para la comunidad, o cualquier otro aspecto del orden público, resulten tan gravemente alterados que el ejercicio de las potestades ordinarias fuera insuficiente para restablecerlo y mantenerlo.</p><p>116.3 - CE - El estado de excepción será declarado por el Gobierno mediante decreto acordado en Consejo de Ministros, previa autorización del Congreso de los Diputados. La autorización y proclamación del estado de excepción deberá determinar expresamente los efectos del mismo, el ámbito territorial a que se extiende y su duración, que no podrá exceder de treinta días, prorrogables por otro plazo igual, con los mismos requisitos.</p><p>Y el El estado de sitio se podrá declarar:</p><p>Cuando se produzca o amenace producirse una insurrección o acto de fuerza contra la soberanía o independencia de España, su integridad territorial o el ordenamiento constitucional, que no pueda resolverse por otros medios.</p><p>116.4 - CE - El estado de sitio será declarado por la mayoría absoluta del Congreso de los Diputados, a propuesta exclusiva del Gobierno. El Congreso determinará su ámbito territorial, duración y condiciones.</p><p>116..5 - CE - No podrá procederse a la disolución del Congreso mientras estén declarados algunos de los estados comprendidos en el presente artículo, quedando automáticamente convocadas las Cámaras si no estuvieren en período de sesiones. Su funcionamiento, así como el de los demás poderes constitucionales del Estado, no podrán interrumpirse durante la vigencia de estos estados.</p><p>Disuelto el Congreso o expirado su mandato, si se produjere alguna de las situaciones que dan lugar a cualquiera de dichos estados, las competencias del Congreso serán asumidas por su Diputación Permanente.</p><p>116.6 -CE - La declaración de los estados de alarma, de excepción y de sitio no modificarán el principio de responsabilidad del Gobierno y de sus agentes reconocidos en la Constitución y en las leyes”.</p>', 6);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '2.7', 'Derechos de nacionalidad. De los Españoles y los extranjeros (Capítulo I)', '<p><strong><span class="uji-ref" data-norma="CE" data-arts="11">art. 11</span> – Derechos de nacionalidad</strong></p><p>“La nacionalidad española se adquiere y se pierde de acuerdo con lo establecido por la ley”.”Ningún español puede ser privado de su nacionalidad”.”El Estado podrá concertar tratados de doble nacionalidad con los países sudamericanos o con aquellos que hayan tenido o tengan una particular vinculación con España”.</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="12">art. 12</span> – Mayoría de edad</strong></p><p>"Los españoles son mayores de edad a los 18 años".</p><p><strong><span class="uji-ref" data-norma="CE" data-arts="13">art. 13</span> – Derechos de los extranjeros</strong></p><p>“Van a gozar de todas las libertades públicas y derechos que garantiza el Título I de la Constitución, en los términos que establezcan los tratados y la ley”.</p><p>Asimismo, tendrán derecho de participación (art.23), atendiendo a criterios de reciprocidad, materializado en el sufragio activo y pasivo en las elecciones municipales.</p><p>13.2. Solamente los españoles serán titulares de los derechos reconocidos en el artículo 23, salvo lo que, atendiendo a criterios de reciprocidad, pueda establecerse por tratado o ley para el derecho de sufragio activo y pasivo en las elecciones municipales.</p><p>Se trata también la extradicción, que sólo se concederá por tratado o ley, atendiendo al criterio de reciprocidad.</p><p>13.3 La extradición sólo se concederá en cumplimiento de un tratado o de la ley, atendiendo al principio de reciprocidad. Quedan excluidos de la extradición los delitos políticos, no considerándose como tales los actos de terrorismo.</p><p>Por último regula el derecho de asilo en España para ciudadanos de otros países y apátridas.</p><p>13.4 La ley establecerá los términos en que los ciudadanos de otros países y los apátridas podrán gozar del derecho de asilo en España.</p>', 7);

-- ================= SECCIÓN 3. EL TRIBUNAL CONSTITUCIONAL
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, contenido_html, orden)
VALUES (1, NULL, 'seccion', '3', 'c3', 'EL TRIBUNAL CONSTITUCIONAL', '<p>Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional.</p><p>La trascendencia e importancia del Tribunal Constitucional se deja ya ver en que cuenta con un título propio, el Título IX. Además, está separado del Título VI del Poder Judicial.</p><p>El Tribunal Constitucional, como intérprete supremo de la Constitución, es independiente de los demás órganos constitucionales y está sometido sólo a la Constitución y a la presente Ley Orgánica. Dos. Es único en su orden y extiende su jurisdicción a todo el territorio nacional.</p><p>“Artículo primero. Ley Orgánica 2/1979Uno. El Tribunal Constitucional, como intérprete supremo de la Constitución, es independiente de los demás órganos constitucionales y está sometido sólo a la Constitución y a la presente Ley Orgánica.Dos. Es único en su orden y extiende su jurisdicción a todo el territorio nacional.”</p><p>Tiene 12 miembros, nombrados por el Rey: 4 por el Congreso y 4 por el Senado, con mayorías de 3/5; 2 por el Gobierno, 2 por el CGPJ.</p><div class="uji-cita"><p><strong>(art. 159.1) CE</strong> El Tribunal Constitucional se compone de 12 miembros nombrados por el Rey; de ellos, cuatro a propuesta del Congreso por mayoría de tres quintos de sus miembros; cuatro a propuesta del Senado, con idéntica mayoría; dos a propuesta del Gobierno, y dos a propuesta del Consejo General del Poder Judicial.</p></div><p>Más de 15 años de ejercicio profesional.</p><p>(art. 159.2) CE - Los miembros del Tribunal Constitucional deberán ser nombrados entre Magistrados y Fiscales, Profesores de Universidad, funcionarios públicos y Abogados, todos ellos juristas de reconocida competencia con más de quince años de ejercicio profesional.</p><p>(art. 159.3) CE - Los miembros del Tribunal Constitucional serán designados por un período de nueve años y se renovarán por terceras partes cada tres.</p><p>(art. 159.4) CE - La condición de miembro del Tribunal Constitucional es incompatible: con todo mandato representativo; con los cargos políticos o administrativos; con el desempeño de funciones directivas en un partido político o en un sindicato y con el empleo al servicio de los mismos; con el ejercicio de las carreras judicial y fiscal, y con cualquier actividad profesional o mercantil.</p><p>En lo demás los miembros del Tribunal Constitucional tendrán las incompatibilidades propias de los miembros del poder judicial.</p><p>(art. 159.5) CE - Los miembros del Tribunal Constitucional serán independientes e inamovibles en el ejercicio de su mandato.</p><p>(art. 160) CE - El Presidente del Tribunal Constitucional será nombrado entre sus miembros por el Rey, a propuesta del mismo Tribunal en pleno y por un período de tres años.</p><p>(art. 161.1) CE - El Tribunal Constitucional tiene jurisdicción en todo el territorio español y es competente para conocer:</p><p>a) Del recurso de inconstitucionalidad contra leyes y disposiciones normativas con fuerza de ley. La declaración de inconstitucionalidad de una norma jurídica con rango de ley, interpretada por la jurisprudencia, afectará a ésta, si bien la sentencia o sentencias recaídas no perderán el valor de cosa juzgada.</p><p>b) Del recurso de amparo por violación de los derechos y libertades referidos en el artículo 53, 2, de esta Constitución, en los casos y formas que la ley establezca.</p><p>c) De los conflictos de competencia entre el Estado y las Comunidades Autónomas o de los de éstas entre sí.</p><p>d) De las demás materias que le atribuyan la Constitución o las leyes orgánicas.</p><p>(art. 161.2) CE - El Gobierno podrá impugnar ante el Tribunal Constitucional las disposiciones y resoluciones adoptadas por los órganos de las Comunidades Autónomas. La impugnación producirá la suspensión de la disposición o resolución recurrida, pero el Tribunal, en su caso, deberá ratificarla o levantarla en un plazo no superior a cinco meses.</p><p>(art. 162.1) CE - Están legitimados:</p><p>a) Para interponer el recurso de inconstitucionalidad, el Presidente del Gobierno, el Defensor del Pueblo, 50 Diputados, 50 Senadores, los órganos colegiados ejecutivos de las Comunidades Autónomas y, en su caso, las Asambleas de las mismas.</p><p>b) Para interponer el recurso de amparo, toda persona natural o jurídica que invoque un interés legítimo, así como el Defensor del Pueblo y el Ministerio Fiscal.</p><p>(art. 162.2) CE - En los demás casos, la ley orgánica determinará las personas y órganos legitimados.</p><p>(art. 163) CE - Cuando un órgano judicial considere, en algún proceso, que una norma con rango de ley, aplicable al caso, de cuya validez dependa el fallo, pueda ser contraria a la Constitución, planteará la cuestión ante el Tribunal Constitucional en los supuestos, en la forma y con los efectos que establezca la ley, que en ningún caso serán suspensivos.</p><p>(art. 164.1) CE - Las sentencias del Tribunal Constitucional se publicarán en el boletín oficial del Estado con los votos particulares, si los hubiere. Tienen el valor de cosa juzgada a partir del día siguiente de su publicación y no cabe recurso alguno contra ellas. Las que declaren la inconstitucionalidad de una ley o de una norma con fuerza de ley y todas las que no se limiten a la estimación subjetiva de un derecho, tienen plenos efectos frente a todos.</p><p>(art. 164.2) CE - Salvo que en el fallo se disponga otra cosa, subsistirá la vigencia de la ley en la parte no afectada por la inconstitucionalidad.</p><p>(art. 165) CE - Una ley orgánica regulará el funcionamiento del Tribunal Constitucional, el estatuto de sus miembros, el procedimiento ante el mismo y las condiciones para el ejercicio de las acciones.</p><p>La Constitución Española de 1978 configura en su Título IX al Tribunal Constitucional como uno de los órganos constitucionales, al que específicamente se confía la defensa de la Norma Fundamental en su dimensión jurídica y por métodos jurisdiccionales.</p><p>Pieza fundamental del Estado social y democrático de Derecho, el Tribunal Constitucional es el intérprete supremo de la Constitución. Único en su orden y con jurisdicción en todo el territorio nacional, ejerce las competencias definidas en el artículo 161 de la Constitución.</p><p>El Tribunal Constitucional es independiente de los demás órganos constitucionales – no forma parte del Poder Judicial - y está sometido solo a la Constitución y a su propia Ley Orgánica.</p><p>Constituido solemnemente bajo la presidencia de Su Majestad el Rey Don Juan Carlos el día 12 de julio de 1980, el Tribunal Constitucional viene ejerciendo desde el día 15 de ese mes las competencias que le atribuyen la Constitución y su Ley Orgánica.</p><p>Las previsiones constitucionales sobre el Tribunal han sido desarrolladas por la Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional y sus sucesivas reformas, que, de acuerdo con la Constitución (art. 165), regula el funcionamiento del Tribunal, el estatuto de sus miembros, los procedimientos ante el mismo y las condiciones para el ejercicio de las acciones. En virtud de la potestad reglamentaria reconocida por su propia Ley Orgánica (art. 2.2), el Tribunal ha dictado, con fecha 5 de julio de 1990, el vigente Reglamento de Organización y Personal.</p><p>La primera experiencia de un Tribunal Constitucional en España tuvo lugar durante la vigencia de la Constitución republicana de 1931, que estableció con el Tribunal de Garantías Constitucionales un sistema de control de la constitucionalidad notablemente distinto al configurado por la Constitución de 1978.</p><p>Sin perjuicio de su propia originalidad, el sistema actual en sus líneas generales toma como modelo el sistema austriaco y alemán de Justicia constitucional concentrada y especializada, frente a la Justicia constitucional difusa o la compartida con otras jurisdicciones.</p><p>El Pleno del Tribunal elige de entre sus miembros, por votación secreta, al Presidente; nombrado por el Rey, su mandato es de tres años, con la posibilidad de una sola reelección (art. 160 CE y art. 9 LOTC). Por el mismo procedimiento es elegido, también por tres años, el Vicepresidente del Tribunal (art. 9.4 LOTC).</p><p>Artículo sexto. Ley Orgánica 2/1979Uno. El Tribunal Constitucional actúa en Pleno, en Sala o en Sección.Dos. El Pleno está integrado por todos los Magistrados del Tribunal. Lo preside elPresidente del Tribunal y, en su defecto, el Vicepresidente y, a falta de ambos, el Magistrado más antiguo en el cargo y, en caso de igual antigüedad, el de mayor edad.Artículo séptimo. Ley Orgánica 2/1979Uno. El Tribunal Constitucional consta de dos Salas. Cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno.Dos. El Presidente del Tribunal lo es también de la Sala Primera, que presidirá en su defecto, el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad.Tres. El Vicepresidente del Tribunal presidirá en la Sala Segunda y, en su defecto, elMagistrado más antiguo y, en caso de igual antigüedad, el de mayor edad.</p><p>Artículo veintidós. Ley Orgánica 2/1979Los Magistrados del Tribunal Constitucional ejercerán su función de acuerdo con los principios de imparcialidad y dignidad inherentes a la misma; no podrán ser perseguidos por las opiniones expresadas en el ejercicio de sus funciones; serán inamovibles y no podrán ser destituidos ni suspendidos sino por alguna de las causas que esta Ley establece.Artículo veintitrés. Ley Orgánica 2/1979Uno. Los Magistrados del Tribunal Constitucional cesan por alguna de las causassiguientes: Primero, por renuncia aceptada por el Presidente del Tribunal; segundo, por expiración del plazo de su nombramiento; tercero, por incurrir en alguna causa de incapacidad de las previstas para los miembros del Poder Judicial; cuarto, porincompatibilidad sobrevenida; quinto, por dejar de atender con diligencia los deberes de su cargo; sexto, por violar la reserva propia de su función; séptimo, por haber sido declarado responsable civilmente por dolo o condenado por delito doloso o por culpa grave.Dos. El cese o la vacante en el cargo de Magistrado del Tribunal Constitucional, en los casos primero y segundo, así como en el de fallecimiento, se decretará por el Presidente. En los restantes supuestos decidirá el Tribunal en Pleno, por mayoría simple en los casos tercero y cuarto y por mayoría de las tres cuartas partes de sus miembros en los demás casos.</p>', 3);
SET @seccion_id := LAST_INSERT_ID();


-- ================= SECCIÓN 4. EL DEFENSOR DEL PUEBLO
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, contenido_html, orden)
VALUES (1, NULL, 'seccion', '4', 'c4', 'EL DEFENSOR DEL PUEBLO', '<p><strong>Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</strong></p><p>El Defensor del Pueblo español es un órgano encargado principalmente de la defensa de los derechos fundamentales y supervisar la actividad de la Administración con los administrados. Es el alto comisionado de las Cortes Generales y actúa como representante de los españoles.</p><p>Se encuentra regulado constitucionalmente mediante el artículo 54 del capítulo 4 del título 1, denominado “de las garantías de las libertades y derechos fundamentales”. Y desarrollado mediante la Ley Orgánica 3/81 de 6 de abril, del Defensor del pueblo.</p><div class="uji-cita"><p><strong>(art. 54)</strong> Una ley orgánica regulará la institución del Defensor del Pueblo, como alto comisionado de las Cortes Generales, designado por éstas para la defensa de los derechos comprendidos en este Título, a cuyo efecto podrá supervisar la actividad de la Administración, dando cuenta a las Cortes Generales”.</p></div>', 4);
SET @seccion_id := LAST_INSERT_ID();

INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '4.1', 'Funciones y competencia', '<p>El Defensor del Pueblo se encarga de defender los derechos y libertades de los españoles, además de la supervisión de las actuaciones de las Administraciones en las relaciones con sus administrados, evitando situaciones injustas y perjudiciales.</p><p>Actúa de forma informal y gratuita, de oficio o a instancia del interesado. Por lo tanto, toda persona puede presentar una queja gratis y sin formalidades.</p><p>No está sujeto a mandato imperativo ni recibe órdenes de ninguna autoridad, es decir, desempeña sus funciones con total autonomía. Goza de inviolabilidad e inmunidad durante el ejercicio de las actuaciones realizadas en el cargo. Y puede interponer recursos de inconstitucionalidad y amparo (como bien tipifica el art. 162 de la C.Española).</p><p>El Defensor del Pueblo se dirige a las cámaras mediante los presidentes de las mismas. Presentando anualmente informe de las actuaciones realizadas durante el año, pudiendo presentar un informe extraordinario si se tratara de urgente de necesidad.</p><p>Nota importante: Todo poder público está obligado a prestar la ayuda que solicite con carácter preferente y urgente en sus investigaciones. Mediante colaboraciones y documentos (incluso cuando se trate de documentos secretos).</p>', 1);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '4.2', 'Elección y nombramiento', '<p>El Defensor del Pueblo español es elegido por las Cortes generales por un período de 5 años con posible reelección. Los requisitos son, que el candidato debe ser español y mayor de edad y estar en pleno uso de sus derechos civiles y políticos.</p><p><strong>Proceso de elección</strong></p><p>Primero la comisión mixta encargada de las relaciones con el defensor elegirán unos candidatos en el plazo de 10 días. Los plenos de las cámaras tendrán un plazo no superior a 20 días para presentar su elección de los candidatos propuestos por la comisión. Primero vota el congreso, adquiriendo el apoyo el que supere la aprobación de los 3/5 de los miembros. Y después es ratificado por el Senado que realiza la misma votación.</p><p>Si no se alcanza los 3/5 con ningún candidato: la comisión mixta presenta varias propuestas durante el plazo máximo de 1 mes. Y una vez se obtenga los 3/5 del pleno del congreso y la ratificación por mayoría absoluta del Senado se dará por concluida su elección.</p><p>Actual sede del Defensor del Pueblo en Madrid, Palacio de los marqueses de Bermejillo del Rey.</p><p><strong>Toma de posesión</strong></p><p>El defensor del pueblo tomará posesión del cargo ante las mesas de ambas cámaras y los presidentes del congreso y del senado acreditarán con su firma el nombramiento del Defensor del Pueblo, publicándose posteriormente en el BOE.</p><p><strong>Secretaría, adjuntos y su elección</strong></p><p>El defensor del pueblo está formado por el defensor, por 2 adjuntos y por una secretaría general formando así la Junta de Coordinación y Régimen interior, que asistirá y asesorará al defensor en la realización de sus competencias.</p><p>El defensor del pueblo delega en sus adjuntos las funciones y son nombrados y separados por el defensor, previa conformidad de las ambas cámaras. Al igual que el Defensor del Pueblo son inviolables e inmunes en el cumplimiento de sus funciones. Su nombramiento también será publicado en el BOE.</p><p>Nota importante: Los adjuntos cesarán en el momento que llegue al cargo otro Defensor del Pueblo.</p><p><strong>Cese, sustitución e incompatibilidades</strong></p><p>El Defensor del Pueblo cesará:</p><p>Cuando renuncie al cargo.</p><p>Por expiración del plazo de su nombramiento (si no ha sido reelegido).</p><p>Por haber sido condenado por un delito doloso (mediante sentencia firme).</p><p>Por actuar con negligencia en el cumplimiento de las obligaciones y deberes del cargo.</p><p>O en todo caso, por muerte o incapacidad.</p><p>En los casos de que el defensor renuncie, muera o expire el plazo del mandato, el presidente del congreso declarará la vacante del puesto y comenzarán a ejercer sus funciones los adjuntos.</p><p>Y en los demás casos, por actuación negligente, condena o incapacidad, las Cortes elegirán por mayoría cualificada de 3/5 el siguiente candidato, previa audiencia con el interesado.</p><p><strong>Incompatibilidades</strong></p><p>El Defensor del Pueblo está sometido a un régimen de incompatibilidades, de las cuales se renunciará en el plazo de 10 días desde que se publicó el nombramiento y en todo caso antes de la toma de posesión. Las incompatibilidades con su cargo son:</p><p>Cualquier mandato representativo y cargo político.</p><p>Permanencia en activo en cualquier administración pública o cualquier actividad profesional, liberal, mercantil o laboral.</p><p>Con el ejercicio de las carreras judicial y fiscal.</p><p>Afiliación a partido político, sindicato, asociación, fundación o la realización de funciones en las mismas.</p><p>El Defensor del Pueblo será juzgado únicamente por la Sala de lo Penal del Tribunal Supremo.</p><p><strong>¿Cómo presentar una queja al defensor del pueblo?</strong></p><p>Puede presentar una queja cualquier persona natural o jurídica (y asociaciones) que presente un interés legítimo. No será motivo de restricción, la edad, sexo, nacionalidad, incapacidad legal del interesado, el internamiento en un centro penitenciario, etc.</p><p>Se puede presentar en persona, por correo y ahora también online en su página web.</p><p>Toda persona puede presentar quejas ante él, es gratuito y sin ningún tipo de formalidad. El Defensor del Pueblo, acusa un recibo de la queja y posteriormente la tramita. La actividad del defensor del pueblo no se verá interrumpida por la declaración de los estados de sitio o excepción o por la disolución de las Cortes, dirigiéndose en este último caso a las Diputaciones Permanentes.</p><p>Las quejas deberán reunir los siguientes requisitos:</p><p>Debe estar firmada por el interesado.</p><p>Indicar su nombre, apellidos y domicilio.</p><p>La descripción razonada por escrito.</p><p>No se aceptarán las quejas:</p><p>Que sean anónimas.</p><p><strong>Que adviertan mala fe, carencia de fundamento…</strong></p><p>Desde el 1 de enero de 2014 está disponible la consulta del procedimiento para poder seguirlo de cerca, con información muy detallada como son las fechas, administración, organismo que tiene que dar respuesta, etc.</p><p>No podrán presentar quejas al Defensor del Pueblo las autoridades administrativas en asuntos de su competencia.</p>', 2);

-- ================= SECCIÓN 5. La Corona
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, contenido_html, orden)
VALUES (1, NULL, 'seccion', '5', 'c5', 'La Corona', '<p>La institución de la Corona está regulada en el Título II de la Constitución.</p>', 5);
SET @seccion_id := LAST_INSERT_ID();

INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '5.1', 'Jefe del Estado', '<p>Hablábamos de una Parte Orgánica de la Constitución, y ya en el Título II, De la Corona, vemos un ejemplo. Se declara al Rey como Jefe de Estado, o sea, como un órgano constitucional.</p>', 1);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '5.2', 'Funciones simbólico-representativas', '<p>Además de otras funciones que le atribuyen la Constitución y las leyes, también asume funciones simbólicas y de representación: “símbolo de su unidad y permanencia”, “árbitro y moderador”, “la más alta representación”.</p><div class="uji-cita"><p><strong>Art 56.1.-CE</strong> El Rey es el Jefe del Estado, símbolo de su unidad y permanencia, arbitra y modera el funcionamiento regular de las instituciones, asume la más alta representación del Estado español en las relaciones internacionales, especialmente con las naciones de su comunidad histórica, y ejerce las funciones que le atribuyen expresamente la Constitución y las leyes”.</p></div>', 2);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '5.3', 'Título y tratamiento', '<div class="uji-cita"><p><strong>Art 56.2. -CE</strong> Su título es el de Rey de España y podrá utilizar los demás que correspondan a la Corona”.</p></div><p>El titular de la Corona recibirá el nombre de Rey o Reina de España y recibirá el tratamiento de Majestad.</p>', 3);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '5.4', 'Inviolabilidad e Irresponsabilidad', '<p>La persona del Rey es inviolable, y no está sujeta a responsabilidad ya que sus actos son refrendados, y la responsabilidad es de quien los refrenda. La mayoría de los refrendos atañen al Presidente del Gobierno, salvo algunas excepciones en las que quien refrenda los actos del rey es el Presidente del Congreso.</p><div class="uji-cita"><p><strong>Art 56.3. -CE</strong> La persona del Rey es inviolable y no está sujeta a responsabilidad. Sus actos estarán siempre refrendados en la forma establecida en el artículo 64, careciendo de validez sin dicho refrendo, salvo lo dispuesto en el artículo 65.2”.</p></div><div class="uji-cita"><p><strong>Artículo 64.1 -CE</strong> Los actos del Rey serán refrendados por el Presidente del Gobierno y, en su caso, por los Ministros competentes. La propuesta y el nombramiento del Presidente del Gobierno, y la disolución prevista en el artículo 99, serán refrendados por el Presidente del Congreso.</p></div><p>64.2 -CE-- De los actos del Rey serán responsables las personas que los refrenden”.</p><p>Según la Ley de Enjuiciamiento Criminal, el Rey , la Reina, sus consortes, el Príncipe heredero o los posibles regentes están exentos de declarar ante Jueces y Tribunales.</p><p><strong>Funciones</strong></p><p>La Constitución enumera algunas de las muchas funciones del Rey.</p><div class="uji-cita"><p><strong>Art. 62 -CE</strong> Corresponde al Rey:</p></div><p>a) Sancionar y promulgar las leyes.</p><p>b) Convocar y disolver las Cortes Generales y convocar elecciones en los términos previstos en la Constitución.</p><p>Convocar a referéndum en los casos previstos en la Constitución.</p><p>d)Proponer el candidato a Presidente de Gobierno y, en su caso, nombrarlo, así como poner fin a sus funciones en los términos previstos en la Constitución.</p><p>e) Nombrar y separar a los miembros del Gobierno, a propuesta de su Presidente.</p><p>f) Expedir los decretos acordados en el Consejo de Ministros, conferir los empleos civiles y militares y conceder honores y distinciones con arreglo a las leyes.</p><p>g) Ser informado de los asuntos de Estado y presidir, a estos efectos, las sesiones del Consejo de Ministros, cuando lo estime oportuno, a petición del Presidente del Gobierno.</p><p>h) El mando supremo de las Fuerzas Armadas.</p><p>i) Ejercer el derecho de gracia con arreglo a la ley, que no podrá autorizar indultos generales.</p><p>j) El Alto Patronazgo de las Reales Academias.</p><p>Es el que firma las leyes, o sea, las sanciona y las promulga para su publicación oficial.</p><p>En general, es el Rey el que hace los nombramientos del Presidente del Gobierno, de los Ministros, de los Presidentes del Congreso y Senado, del Presidente del Tribunal Constitucional, del Presidente del CGPJ.</p><div class="uji-cita"><p><strong>Art. 63.1 -CE</strong> El Rey acredita a los embajadores y otros representantes diplomáticos. Los representantes extranjeros en España están acreditados ante él.</p></div><p>2.Al Rey corresponde manifestar el consentimiento del Estado para obligarse internacionalmente por medio de tratados, de conformidad con la Constitución y las leyes.</p><p>3.Al Rey corresponde, previa autorización de las Cortes Generales, declarar la guerra y hacer la paz”.</p><p>Es el representante a nivel internacional de España para acreditar a los embajadores extranjeros, para obligar al estado español por medio de Tratados internacionales. Además es quien declararía una guerra o firmaría la paz.</p>', 4);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '5.5', 'Sucesión', '<div class="uji-cita"><p><strong>Artículo 57.1 -CE</strong> La Corona de España es hereditaria en los sucesores de S. M. Don Juan Carlos I de Borbón, legítimo heredero de la dinastía histórica. La sucesión en el trono seguirá el orden regular de primogenitura y representación, siendo preferida siempre la línea anterior a las posteriores; en la misma línea, el grado más próximo al más remoto; en el mismo grado, el varón a la mujer, y en el mismo sexo, la persona de más edad a la de menos ”.</p></div><ul class="uji-lista"><li>Sucesores de Juan Carlos I.</li><li>Preferida la línea anterior de representación ( o sea, los descendientes, y no los ascendientes).</li><li>Preferido el grado más próximo de parentesco.</li><li>Primogenitura preferente en el mismo grado de representación (el varón de más edad de los hermanos).</li></ul><p><strong>Príncipe de Asturias – Así se designa al sucesor a la Corona.</strong></p><p>Sin sucesión – Las Cortes Generales proveerán la sucesión.</p><p><strong>Exclusiones, abdicaciones y renuncias</strong></p><div class="uji-cita"><p><strong>Art. 57.4 -CE</strong> Aquellas personas que teniendo derecho a la sucesión en el trono contrajeren matrimonio contra la expresa prohibición del Rey y de las Cortes Generales, quedarán excluidas en la sucesión a la Corona por sí y sus descendientes”.</p></div><div class="uji-cita"><p><strong>Art. 57.5 -CE</strong> Las abdicaciones y renuncias y cualquier duda de hecho o de derecho que ocurra en el orden de sucesión a la Corona se resolverán por una ley orgánica”.</p></div><p><strong>La Reina</strong></p><div class="uji-cita"><p><strong>Artículo 58 -CE</strong> La Reina consorte o el consorte de la Reina no podrán asumir funciones constitucionales, salvo lo dispuesto para la Regencia”.</p></div><p><strong>Regencia</strong></p><p>Si el heredero menor de edad – Regencia por el pariente de más edad más cerca de la posible sucesión.</p><p>Si Rey inhabilitado – Regencia por Príncipe heredero, si fuese mayor de edad.</p><p>Si no hubiere ninguna persona a quien corresponda la Regencia, ésta será nombrada por las Cortes Generales, y se compondrá de una, tres o cinco personas.</p><p>Para ejercer la Regencia es preciso ser español y mayor de edad.</p><p>La Regencia se ejercerá por mandato constitucional y siempre en nombre del Rey.</p><p><strong>Tutela</strong></p><div class="uji-cita"><p><strong>Artículo 60.1 -CE</strong> Será tutor del Rey menor la persona que en su testamento hubiese nombrado el Rey difunto, siempre que sea mayor de edad y español de nacimiento; si no lo hubiese nombrado, será tutor el padre o la madre; mientras permanezcan viudos. En su defecto, lo nombrarán las Cortes Generales, pero no podrán acumularse los cargos de Regente y de tutor sino en el padre, madre o ascendientes directos del Rey”.</p></div><div class="uji-cita"><p><strong>60.2 -CE</strong> El ejercicio de la tutela es también incompatible con el de todo cargo o representación política”.</p></div><p><strong>Proclamación y juramento</strong></p><div class="uji-cita"><p><strong>Art. 61.1 -CE</strong> El Rey, al ser proclamado ante las Cortes Generales, prestará juramento de desempeñar fielmente sus funciones, guardar y hacer guardar la Constitución y las leyes y respetar los derechos de los ciudadanos y de las Comunidades Autónomas”.</p></div><div class="uji-cita"><p><strong>Art. 61.2 -CE</strong> El Príncipe heredero, al alcanzar la mayoría de edad, y el Regente o Regentes al hacerse cargo de sus funciones, prestarán el mismo juramento, así como el de fidelidad al Rey”.</p></div>', 5);

-- ================= SECCIÓN 6. Poder Judicial
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, contenido_html, orden)
VALUES (1, NULL, 'seccion', '6', 'c6', 'Poder Judicial', '<p>La institución del Poder Judicial está regulada en el Título VI de la Constitución. Del artículo 117 al 127.</p>', 6);
SET @seccion_id := LAST_INSERT_ID();

INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '6.1', 'Independencia del Poder Judicial', '<div class="uji-cita"><p><strong>Artículo 117.1 -CE</strong> La justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados integrantes del poder judicial, independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley”.</p></div>', 1);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (1, @seccion_id, 'epigrafe', '6.2', 'Garantías de independencia', '<p><strong>Inamovilidad</strong></p><div class="uji-cita"><p><strong>117.2 -CE</strong> Los Jueces y Magistrados no podrán ser separados, suspendidos, trasladados ni jubilados sino por alguna de las causas y con las garantías previstas en la ley”.</p></div><p><strong>Potestad única</strong></p><div class="uji-cita"><p><strong>117.3 -CE</strong> El ejercicio de la potestad jurisdiccional en todo tipo de procesos, juzgando y haciendo ejecutar lo juzgado, corresponde exclusiva-mente a los Juzgados y Tribunales determinados por las leyes, según las normas de competencia y procedimiento que las mismas establezcan”.</p></div><p><strong>Exclusividad</strong></p><div class="uji-cita"><p><strong>117.4 -CE</strong> Los Juzgados y Tribunales no ejercerán más funciones que las señaladas en el apartado anterior y las que expresamente les sean atribuidas por ley en garantía de cualquier derecho ”.</p></div><p><strong>Unidad jurisdiccional</strong></p><div class="uji-cita"><p><strong>117.5 -CE</strong> El principio de unidad jurisdiccional es la base de la organización y funcionamiento de los Tribunales. La ley regulará el ejercicio de la jurisdicción militar en el ámbito estrictamente castrense y en los supuestos de estado de sitio, de acuerdo con los principios de la Constitución”.</p></div><p><strong>Obligaciones con la justicia</strong></p><div class="uji-cita"><p><strong>118 -CE</strong> Es obligado cumplir las sentencias y demás resoluciones firmes de los Jueces y Tribunales, así como prestar la colaboración requerida por éstos en el curso del proceso y en la ejecución de lo resuelto”.</p></div><p><strong>Garantías de los ciudadanos</strong></p><p><strong>Gratuidad</strong></p><div class="uji-cita"><p><strong>119 -CE</strong> La justicia será gratuita cuando así lo disponga la ley, y, en todo caso, respecto de quienes acrediten insuficiencia de recursos para litigar ”.</p></div><p><strong>Publicidad</strong></p><div class="uji-cita"><p><strong>Artículo 120.1 -CE</strong> Las actuaciones judiciales serán públicas, con las excepciones que prevean las leyes de procedimiento”.</p></div><div class="uji-cita"><p><strong>2</strong> El procedimiento será predominantemente oral, sobre todo en materia criminal”.</p></div><div class="uji-cita"><p><strong>3</strong> Las sentencias serán siempre motivadas y se pronunciarán en audiencia pública”.</p></div><p><strong>Indemnización por errores judiciales</strong></p><div class="uji-cita"><p><strong>Art. 121 -CE</strong> Los daños causados por error judicial, así como los que sean consecuencia del funcionamiento anormal de la Administración de Justicia, darán derecho a una indemnización a cargo del Estado, conforme a la Ley.”.</p></div><p><strong>Organización – Consejo General del Poder Judicial</strong></p><p>El artículo 122 señala la organización del Poder Judicial.</p><ul class="uji-lista"><li>Se establecerá por Ley Orgánica todo lo concerniente al Poder Judicial.</li><li>El CGPJ como órgano de gobierno del Poder Judicial.</li><li>Organización CGPJ: Presidente, el mismo que el del Tribunal Supremo.</li><li>20 miembros:</li><li>Nombrados por el Rey. Por 5 años.</li><li>12 entre Jueces y Magistrados, según Ley Orgánica.</li><li>4 entre abogados y juristas (15 años ejercicio y reconocida competencia). Por Congreso, mayoría 3/5.</li><li>4 entre abogados y juristas (15 años ejercicio y reconocida competencia). Por Senado, mayoría 3/5.</li></ul><p><strong>Tribunal Supremo</strong></p><p>El Tribunal Supremo (TS) es el órgano judicial que se encuentra en la cúspide del poder judicial español. Su jurisdicción se extiende a todo el territorio nacional y es el órgano superior en todos los órdenes jurisdiccionales: civil, penal, contencioso-administrativo, social y militar.</p><div class="uji-cita"><p><strong>Artículo 123.1 -CE</strong> El Tribunal Supremo, con jurisdicción en toda España, es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de garantías constitucionales”.</p></div><p>El presidente es elegido en el Pleno del Tribunal si este ha obtenido la confianza de tres quintos de los miembros del Pleno. Si este no fuere el caso, se llevaría a cabo una segunda votación entre los dos candidatos más votados en la primera votación y, el que obtuviese más apoyos, es elegido presidente. Una vez elegido, se le comunicará la elección al rey que lo nombrará definitivamente como presidente.</p><div class="uji-cita"><p><strong>123.2 -CE</strong> El Presidente del Tribunal Supremo será nombrado por el Rey, a propuesta del Consejo General del Poder Judicial, en la forma que determine la ley”.</p></div><p>El Tribunal Supremo es el principal tribunal español de casación, encomendado con la misión de garantizar la aplicación uniforme de las leyes en todo el territorio nacional, y asegurar que los órganos judiciales de todo el país aplican los mismos criterios interpretativos de estas.</p><p>El Tribunal Supremo está compuesto por el presidente del Tribunal Supremo y por un número indeterminado de magistrados adscritos a las diversas salas que lo integran, todos ellos nombrados por el rey a propuesta del Consejo General del Poder Judicial.</p><p>Actualmente cuenta con 79 magistrados que se reparten entre las cinco Salas que componen el Tribunal, una por cada orden jurisdiccional.</p><p><strong>El Ministerio Fiscal</strong></p><div class="uji-cita"><p><strong>Artículo 124.1 -CE</strong> El Ministerio Fiscal, sin perjuicio de las funciones encomendadas a otros órganos, tiene por misión promover la acción de la justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley, de oficio o a petición de los interesados, así como velar por la independencia de los Tribunales y procurar ante éstos la satisfacción del interés social”.</p></div><div class="uji-cita"><p><strong>124.2 -CE</strong> El Ministerio Fiscal ejerce sus funciones por medio de órganos propios conforme a los principios de unidad de actuación y dependencia jerárquica y con sujeción, en todo caso, a los de legalidad e imparcialidad”.</p></div><div class="uji-cita"><p><strong>124.3 -CE</strong> La ley regulará el estatuto orgánico del Ministerio Fiscal”.</p></div><div class="uji-cita"><p><strong>124.4 -CE</strong> El Fiscal General del Estado será nombrado por el Rey, a propuesta del Gobierno, oído el Consejo General del poder judicial”.</p></div><p><strong>Jurado</strong></p><div class="uji-cita"><p><strong>Artículo 125</strong> Los ciudadanos podrán ejercer la acción popular y participar en la Administración de Justicia mediante la institución del Jurado, en la forma y con respecto a aquellos procesos penales que la ley determine, así como en los Tribunales consuetudinarios y tradicionales”.</p></div><p><strong>Policía Judicial</strong></p><div class="uji-cita"><p><strong>Artículo 126 -CE</strong> La policía judicial depende de los Jueces, de los Tribunales y del Ministerio Fiscal en sus funciones de averiguación del delito y descubrimiento y aseguramiento del delincuente, en los términos que la ley establezca”.</p></div><div class="uji-cita"><p><strong>Art. 127.1 -CE</strong> Los Jueces y Magistrados, así como los Fiscales, mientras se hallen en activo, no podrán desempeñar otros cargos públicos, ni pertenecer a partidos políticos o sindicatos. La ley establecerá el sistema y modalidades de asociación profesional de los Jueces, Magistrados y Fiscales”.</p></div><div class="uji-cita"><p><strong>Art. 127.2 -CE</strong> La ley establecerá el régimen de incompatibilidades de los miembros del poder judicial, que deberá asegurar la total independencia de los mismos”.</p></div>', 2);

-- ================= SECCIÓN 7. REFORMA CONSTITUCIONAL
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, contenido_html, orden)
VALUES (1, NULL, 'seccion', '7', 'c1', 'REFORMA CONSTITUCIONAL', '<p>La Reforma Constitucional se trata en el Título X, y último, de la Constitución.</p><p>Como comentamos como una de las características de la CE, ésta es rígida, por lo difícil que es reformarla por las amplias mayorías que se necesitan para ello.</p><div class="uji-cita"><p><strong>Artículo 166 -CE</strong> La iniciativa de reforma constitucional se ejercerá en los términos previstos en los apartados 1 y 2 del artículo 87”.</p></div><p>El artículo 87, del Título III, trata sobre la iniciativa legislativa y a quienes corresponde.</p><p><strong>Reforma Constitucional</strong></p><ul class="uji-lista"><li>Por mayoría de 3/5 en ambas Cámaras, Congreso y Senado.</li><li>Si no acuerdo:</li><li>Comisión paritaria Congreso Senado. Presenta texto en ambas Cámaras.</li><li>Si aún sin acuerdo, y sí absoluta en el Senado, puede aprobarse por 2/3 en Congreso.</li><li>- Cuando acuerdo:</li><li>- 15 días para pedir Referendum. Lo puede solicitar una décima parte dell Congreso o del Senado.</li></ul><p><strong><span class="uji-ref" data-norma="CE" data-arts="167">art. 167</span></strong></p><p>Los proyectos de reforma constitucional deberán ser aprobados por una mayoría de tres quintos de cada una de las Cámaras. Si no hubiera acuerdo entre ambas, se intentará obtenerlo mediante la creación de una Comisión de composición paritaria de Diputados y Senadores, que presentará un texto que será votado por el Congreso y el Senado.</p><p>2. De no lograrse la aprobación mediante el procedimiento del apartado anterior, y siempre que el texto hubiere obtenido el voto favorable de la mayoría absoluta del Senado, el Congreso, por mayoría de dos tercios, podrá aprobar la reforma.</p><p>3. Aprobada la reforma por las Cortes Generales, será sometida a referéndum para su ratificación cuando así lo soliciten, dentro de los quince días siguientes a su aprobación, una décima parte de los miembros de cualquiera de las Cámaras</p><p>Revisión total (o parcial del Preliminar, Cap 2,Sec1 del Título I, y Título 2)</p><p>En estos casos se necesitan los dos tercios de cada Cámara. A continuación se disuelven las Cámaras. Las nuevas elegidas deben ratificar por 2/3 la decisión de las anteriores Cortes y aprobar , asimismo por 2/3 el nuevo texto constitucional.</p><div class="uji-cita"><p><strong>Artículo 168.1 -CE</strong> Cuando se propusiere la revisión total de la Constitución o una parcial que afecte al Título Preliminar, al Capítulo Segundo, Sección 1.ª del Título I, o al Título II, se procederá a la aprobación del principio por mayoría de dos tercios de cada Cámara, y a la disolución inmediata de las Cortes.</p></div><div class="uji-cita"><p><strong>168.2 -CE</strong> Las Cámaras elegidas deberán ratificar la decisión y proceder al estudio del nuevo texto constitucional, que deberá ser aprobado por mayoría de dos tercios de ambas Cámaras”.</p></div><div class="uji-cita"><p><strong>168.3 -CE</strong> Aprobada la reforma por las Cortes Generales, será sometida a referéndum para su ratificación”.</p></div><div class="uji-cita"><p><strong>169 -CE</strong> No podrá iniciarse la reforma constitucional en tiempo de guerra o de vigencia de alguno de los estados previstos en el artículo 116”.</p></div>', 7);
SET @seccion_id := LAST_INSERT_ID();


-- ================= SECCIÓN 8. ECONOMÍA Y HACIENDA
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, contenido_html, orden)
VALUES (1, NULL, 'seccion', '8', 'c2', 'ECONOMÍA Y HACIENDA', '<p>El Título VII es el que trata sobre Economía y Hacienda. Del artículo 128 al 136.</p><p>Establece varias prioridades sobre los bienes públicos:</p><div class="uji-cita"><p><strong>Artículo 132.1 -CE</strong> La ley regulará el régimen jurídico de los bienes de dominio público y de los comunales, inspirándose en los principios de inalienabilidad, imprescriptibilidad e inembargabilidad, así como su desafectación”.</p></div><div class="uji-cita"><p><strong>132.2 -CE</strong> Son bienes de dominio público estatal los que determine la ley y, en todo caso, la zona marítimo-terrestre, las playas, el mar territorial y los recursos naturales de la zona económica y la plataforma continental”.</p></div><div class="uji-cita"><p><strong>132.3 -CE</strong> Por ley se regularán el Patrimonio del Estado y el Patrimonio Nacional, su administración, defensa y conservación”.</p></div><p>El artículo 133 versa sobre la potestad Tributaria del estado.</p><div class="uji-cita"><p><strong>Artículo 133.1 -CE</strong> La potestad originaria para establecer los tributos corresponde exclusivamente al Estado, mediante ley”.</p></div><div class="uji-cita"><p><strong>133.2 -CE</strong> Las Comunidades Autónomas y las Corporaciones locales podrán establecer y exigir tributos, de acuerdo con la Constitución y las leyes”.</p></div><div class="uji-cita"><p><strong>133.3 -CE</strong> Todo beneficio fiscal que afecte a los tributos del Estado deberá establecerse en virtud de ley”.</p></div><div class="uji-cita"><p><strong>133.4 -CE</strong> Las administraciones públicas sólo podrán contraer obligaciones financieras y realizar gastos de acuerdo con las leyes”.</p></div><p>El artículo 134 trata sobre los Presupuestos Generales del Estado:</p><p>-Lo elabora el Gobierno, lo examinan, enmiendan y aprueban las Cortes.</p><ul class="uji-lista"><li>Tienen carácter anual. El Gobierno debe presentar tres meses antes de la expiración del presupuesto anterior.</li><li>Toda proposición o enmienda que suponga aumento de los créditos o disminución de los ingresos presupuestarios requerirá la conformidad del Gobierno para su tramitación.</li><li>El artículo 135, uno de los que ha sufrido Reforma, trata sobre la estabilidad presupuestaria.</li></ul><p>Por último, el 136 trata sobre el Tribunal de Cuentas.</p><ul class="uji-lista"><li>Depende de las Cortes</li><li>Censura las cuentas el Estado y del sector público.</li><li>Remitirá a las Cortes un informe anual.</li><li>- Misma inmovilidad, independencia e incompatibilidades que los jueces.</li><li>Pleno: Formado por 12 consejeros y un Fiscalizador</li><li>Los consejeros elegidos por 9 años: 6 por el Congreso, 6 por el senado, por mayoría de 3/5.</li><li>Presidente: elegido por 3 años. Nombrado por el rey a propuesta del Pleno.</li></ul><div class="uji-cita"><p><strong>Artículo 136.1 -CE</strong> El Tribunal de Cuentas es el supremo órgano fiscalizador de las cuentas y de la gestión económica del Estado, así como del sector público. Dependerá directamente de las Cortes Generales y ejercerá sus funciones por delegación de ellas en el examen y comprobación de la Cuenta General del Estado”.</p></div><div class="uji-cita"><p><strong>136.2 -CE</strong> Las cuentas del Estado y del sector público estatal se rendirán al Tribunal de Cuentas y serán censuradas por éste”.</p></div><p>“El Tribunal de Cuentas, sin perjuicio de su propia jurisdicción, remitirá a las Cortes Generales un informe anual en el que, cuando proceda, comunicará las infracciones o responsabilidades en que, a su juicio, se hubiere incurrido”.</p><div class="uji-cita"><p><strong>136.3 -CE</strong> Los miembros del Tribunal de Cuentas gozarán de la misma independencia e inamovilidad y estarán sometidos a las mismas incompatibilidades que los Jueces”.</p></div><div class="uji-cita"><p><strong>136.4 -CE</strong> Una ley orgánica regulará la composición, organización y funciones del Tribunal de Cuentas”.</p></div>', 8);
SET @seccion_id := LAST_INSERT_ID();


